use std::collections::btree_map::Range;
use std::collections::BTreeMap;
use std::ops::Bound::{Excluded, Included, Unbounded};

#[derive(Clone, Debug, Default)]
pub struct SortedMap<K, V> {
    inner: BTreeMap<K, V>,
}

impl<K: Ord, V> SortedMap<K, V> {
    pub fn new() -> Self {
        Self {
            inner: BTreeMap::new(),
        }
    }

    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        self.inner.insert(key, value)
    }

    pub fn size(&self) -> usize {
        self.inner.len()
    }

    pub fn contains(&self, key: &K) -> bool {
        self.inner.contains_key(key)
    }

    pub fn erase(&mut self, key: &K) -> Option<V> {
        self.inner.remove(key)
    }

    pub fn find(&self, key: &K) -> Option<(&K, &V)> {
        self.inner.get_key_value(key)
    }

    pub fn lower_bound(&self, key: &K) -> Option<(&K, &V)> {
        self.inner
            .range::<K, _>((Included(key), Unbounded))
            .next()
            .map(|(stored_key, value)| (stored_key, value))
    }

    pub fn upper_bound(&self, key: &K) -> Option<(&K, &V)> {
        self.inner
            .range::<K, _>((Excluded(key), Unbounded))
            .next()
            .map(|(stored_key, value)| (stored_key, value))
    }

    pub fn equal_range(&self, key: &K) -> Range<'_, K, V> {
        self.inner.range::<K, _>((Included(key), Included(key)))
    }

    pub fn clear(&mut self) {
        self.inner.clear();
    }

    pub fn empty(&self) -> bool {
        self.inner.is_empty()
    }
}

impl<K: Ord, V: Default> SortedMap<K, V> {
    pub fn get_or_insert_default(&mut self, key: K) -> &mut V {
        self.inner.entry(key).or_default()
    }
}

impl<K: Ord + Clone, V: Clone> SortedMap<K, V> {
    pub fn keys(&self) -> Vec<K> {
        self.inner.keys().cloned().collect()
    }

    pub fn values(&self) -> Vec<V> {
        self.inner.values().cloned().collect()
    }

    pub fn get_or(&self, key: &K, default: V) -> V {
        self.inner.get(key).cloned().unwrap_or(default)
    }
}

pub fn update<K: Ord + Clone, V: Clone>(destination: &mut SortedMap<K, V>, source: &SortedMap<K, V>) {
    for (key, value) in source.inner.iter() {
        destination.insert(key.clone(), value.clone());
    }
}

